import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"超时与退避","description":"","frontmatter":{"title":"超时与退避","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timeout-backoff.md","filePath":"cs/timeout-backoff.md","lastUpdated":1789023840000}'),h={name:"cs/timeout-backoff.md"};function E(f,a,_,m,u,B){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="超时与退避" tabindex="-1">超时与退避 <a class="header-anchor" href="#超时与退避" aria-label="Permalink to &quot;超时与退避&quot;">​</a></h1><div class="epigraph"><p>超时把「不知道」变成失败。退避让重试错开。没有抖动的同步重试是分布式的惊群，比第一次故障更大。</p><footer>—— 据 Ethernet 的截断二进制指数退避；Dean and Barroso 对重试放大的讨论；Google SRE 实践整理</footer></div><p>上一课<a href="/cs/rate-limit-circuit-breaker">熔断</a>在错误率高时关门。缺口是<strong>门关上之前与半开时</strong>：每次失败立刻重试，下游刚病就被同一波请求再打。本课钉超时选择与指数退避加抖动。后课对冲请求是另一类「同一调用多份」，会再放大。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>超时太长：线程与连接被占，尾延迟变过载。超时太短：慢成功被当失败再重试，执行次数上升，接到<a href="/cs/rpc-semantics">RPC 语义</a>。分层超时必须递减：网关 &gt; 服务 &gt; 下游，否则下层还在跑上层已重试。</p><p>退避：第 \\(k\\) 次等 \\(\\min(cap, b^k)\\) 再加随机抖动。无抖动：所有客户端用同一时钟对齐重试——雪崩。Ethernet 很早就用随机退避拆冲突；RPC 重试是同一形状。</p><p><span class="marginnote">SRE 书强调限制重试预算（retry budget），防止一小撮失败客户端吃光下游。这是限流在时间维。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单调钟量超时，接<a href="/cs/clock-drift">物理时钟</a>。幂等才重试非幂等写。重试预算：一段窗口内重试占比上限。给下游传 deadline，而不是各层各猜。</p>',9)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%A4%B1%E8%B4%A5%20%2F%20%E8%B6%85%E6%97%B6%22%5D%20--%3E%20B%5B%22%E6%8C%87%E6%95%B0%E9%80%80%E9%81%BF%20%2B%20%E6%8A%96%E5%8A%A8%22%5D%0A%20%20B%20--%3E%20BD%5B%22deadline%20%E4%BC%A0%E9%80%92%22%5D%0A%20%20BD%20--%3E%20R%5B%22%E6%9C%89%E9%99%90%E6%AC%A1%E9%87%8D%E8%AF%95%22%5D%0A%20%20R%20--%3E%20CB%5B%22%E4%BB%8D%E5%A4%B1%E8%B4%A5%E5%88%99%E7%86%94%E6%96%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要在熔断打开时还按原预算重试。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重试放大：失败率 \\(p\\) 时若立即重试一次，负载约 \\(1+p\\)，已病系统 \\(p\\) 上升，正反馈。退避与预算把反馈压住。与<a href="/cs/failure-detectors">故障检测器</a>：超时即怀疑，误伤代价是多余重试，不是脑裂（除非重试的是选主）。</p><p>本课不写 TCP RTO 公式全文。也不把无线 CSMA 当数据中心 RPC 的实现。</p><p>Deadline 传播：剩余时间随 RPC 走，避免「上层 1s、下层 5s」的倒置。这是部分同步里把 \\(\\Delta\\) 写成请求字段。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不对冲请求（下一课）。不引入自适应超时的全部估计器（点名：Hedged、percentile）。后课默认：重试必抖动必预算必幂等；超时用单调钟与递减 deadline。尾延迟对冲会故意发第二份，必须算进预算。</p><p>失败后立刻同步重试是把检测器的误伤变成过载。随机化是活性工程，也是安全负载。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>超时定义「不知道」；太短制造假失败与重复执行。</li><li>指数退避必须加抖动；要有重试预算。</li><li>Deadline 向下传递，层间递减。</li><li>出处：指数退避；Dean–Barroso；SRE 实践。</li></ul>',10))])}const D=i(h,[["render",E]]);export{b as __pageData,D as default};
